//! `licenses`: the third-party notices that ship inside the binary.

/// Generated by `cargo about generate about.hbs` (see about.toml); CI fails if
/// the committed file is stale.
pub const THIRD_PARTY_LICENSES: &str = include_str!("../../THIRD_PARTY_LICENSES.md");

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn notices_cover_the_core_dependencies() {
        for name in [
            "ring ",
            "tokio ",
            "axum ",
            "reqwest ",
            "Apache License",
            "MIT License",
        ] {
            assert!(THIRD_PARTY_LICENSES.contains(name), "missing {name:?}");
        }
        assert!(
            !THIRD_PARTY_LICENSES.contains("&quot;"),
            "HTML-escaped output"
        );
    }
}
